def kessler_freight_charge(weight_kg, zone, is_perishable) -> float:
    rates = {
        "inland": 4.20,
        "coastal": 5.75,
        "highland": 9.10,
    }

    if zone not in rates:
        raise ValueError("invalid zone")
    if weight_kg <= 0:
        raise ValueError("weight_kg must be greater than 0")

    base_rate = rates[zone]
    weight = float(weight_kg)

    subtotal = (
        min(weight, 10) * base_rate
        + min(max(weight - 10, 0), 40) * 0.60 * base_rate
        + max(weight - 50, 0) * 0.35 * base_rate
    )

    subtotal_cents = int(round(subtotal * 100))
    if subtotal_cents % 100 == 0:
        subtotal_cents -= 200

    if is_perishable and zone != "highland":
        subtotal_cents += 1850

    return round(subtotal_cents / 100, 2)

